#!/usr/bin/env node
// Acquisition driver for the angular-super-productivity-v2-13-15 ingest.
// Consent VL-LEGACY-CORPUS-2026-08-10. GET only, no credentials, no redirects,
// no retries. Every response is digested and ledgered.
//
// Usage: node acquire.mjs <cacheRoot> <evidenceRoot>

import { createHash } from 'node:crypto';
import { mkdir, writeFile, appendFile } from 'node:fs/promises';
import { join } from 'node:path';

const OWNER = 'johannesjo';
const REPO = 'super-productivity';
const TAG = 'v2.13.15';
const EXPECTED_COMMIT = '2943c5c4f13c3ce4dece0abf4f9c39739dde4192';

const cacheRoot = process.argv[2];
const evidenceRoot = process.argv[3];
const ledgerPath = join(evidenceRoot, 'probe-ledger.ndjson');

const CAPS = {
  maximumAcceptedResponses: 12,
  maximumApiResponseBytes: 16777216,
  maximumArchiveBytes: 134217728,
  maximumAggregateWireBytes: 314572800,
};

const state = { accepted: 0, wireBytes: 0, redirects: 0, requests: [] };

const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

async function probe(url, { maxBytes, stream } = {}) {
  if (state.accepted >= CAPS.maximumAcceptedResponses) {
    throw new Error(`cap exceeded: maximumAcceptedResponses`);
  }
  const startedAt = new Date().toISOString();
  const res = await fetch(url, {
    method: 'GET',
    redirect: 'manual',
    headers: {
      accept: url.startsWith('https://api.github.com')
        ? 'application/vnd.github+json'
        : 'application/octet-stream',
      'accept-encoding': 'identity',
      'user-agent': 'versionless-legacy-corpus-ingest',
    },
  });
  if (res.status >= 300 && res.status < 400) {
    state.redirects += 1;
    throw new Error(`redirect refused: ${url} -> ${res.status}`);
  }
  if (res.status !== 200) throw new Error(`status ${res.status} for ${url}`);
  const body = Buffer.from(await res.arrayBuffer());
  const limit = maxBytes ?? CAPS.maximumApiResponseBytes;
  if (body.length > limit) throw new Error(`cap exceeded: bytes for ${url}`);
  state.accepted += 1;
  state.wireBytes += body.length;
  if (state.wireBytes > CAPS.maximumAggregateWireBytes) {
    throw new Error('cap exceeded: maximumAggregateWireBytes');
  }
  const digest = sha256(body);
  const record = {
    at: startedAt,
    completedAt: new Date().toISOString(),
    endpoint: url,
    method: 'GET',
    status: res.status,
    bytes: body.length,
    sha256: digest,
    contentType: res.headers.get('content-type'),
    credentialsSent: 0,
    redirectsFollowed: 0,
    ...(stream ? { stream } : {}),
  };
  state.requests.push(record);
  await appendFile(ledgerPath, JSON.stringify(record) + '\n');
  return { body, digest, record };
}

const json = (buf) => JSON.parse(buf.toString('utf8'));

await mkdir(join(cacheRoot, 'archive'), { recursive: true });
await mkdir(join(cacheRoot, 'raw'), { recursive: true });
await mkdir(evidenceRoot, { recursive: true });

// 1. repository metadata
const repoRes = await probe(`https://api.github.com/repos/${OWNER}/${REPO}`);
const repoMeta = json(repoRes.body);

// 2. tag ref
const refRes = await probe(
  `https://api.github.com/repos/${OWNER}/${REPO}/git/ref/tags/${TAG}`,
);
const ref = json(refRes.body);

// 3. tag object if annotated
let tagObj = null;
let tagRes = null;
let commitSha = ref.object.sha;
if (ref.object.type === 'tag') {
  tagRes = await probe(
    `https://api.github.com/repos/${OWNER}/${REPO}/git/tags/${ref.object.sha}`,
  );
  tagObj = json(tagRes.body);
  commitSha = tagObj.object.sha;
}

if (commitSha !== EXPECTED_COMMIT) {
  throw new Error(
    `commit mismatch: wire ${commitSha} != scout ${EXPECTED_COMMIT}`,
  );
}

// 4. commit
const commitRes = await probe(
  `https://api.github.com/repos/${OWNER}/${REPO}/git/commits/${commitSha}`,
);
const commit = json(commitRes.body);
const treeSha = commit.tree.sha;

// 5. recursive tree
const treeRes = await probe(
  `https://api.github.com/repos/${OWNER}/${REPO}/git/trees/${treeSha}?recursive=1`,
);
const tree = json(treeRes.body);
await writeFile(join(evidenceRoot, 'probe-tree.json'), treeRes.body);

// 6/7. double archive fetch
const archiveUrl = `https://codeload.github.com/${OWNER}/${REPO}/tar.gz/${commitSha}`;
const a1 = await probe(archiveUrl, {
  maxBytes: CAPS.maximumArchiveBytes,
  stream: 1,
});
await writeFile(join(cacheRoot, 'archive', 'archive-1.tar.gz'), a1.body);
const a2 = await probe(archiveUrl, {
  maxBytes: CAPS.maximumArchiveBytes,
  stream: 2,
});
await writeFile(join(cacheRoot, 'archive', 'archive-2.tar.gz'), a2.body);

const byteIdentical = a1.digest === a2.digest && a1.body.equals(a2.body);

await writeFile(
  join(cacheRoot, 'raw', 'probe.json'),
  JSON.stringify(
    { repoMeta, ref, tagObj, commit, treeSummaryCount: tree.tree.length },
    null,
    2,
  ),
);

const entries = tree.tree;
const counts = {
  treeEntries: entries.length,
  treeBlobs: entries.filter((e) => e.type === 'blob').length,
  treeDirectories: entries.filter((e) => e.type === 'tree').length,
  treeSymlinks: entries.filter((e) => e.mode === '120000').length,
  treeGitlinks: entries.filter((e) => e.type === 'commit').length,
  treeExecutableBlobs: entries.filter((e) => e.mode === '100755').length,
  treeTruncated: Boolean(tree.truncated),
};

const summary = {
  repository: {
    id: repoMeta.id,
    fullName: repoMeta.full_name,
    private: repoMeta.private,
    archived: repoMeta.archived,
    disabled: repoMeta.disabled,
    defaultBranch: repoMeta.default_branch,
    licenseSpdx: repoMeta.license ? repoMeta.license.spdx_id : null,
    responseBytes: repoRes.record.bytes,
    responseSha256: repoRes.digest,
  },
  revision: {
    ref: ref.ref,
    tagObjectSha: tagObj ? tagObj.sha : null,
    tagKind: ref.object.type === 'tag' ? 'annotated' : 'lightweight',
    tagDate: tagObj ? tagObj.tagger.date : null,
    tagMessage: tagObj ? tagObj.message.trim() : null,
    tagVerification: tagObj
      ? tagObj.verification && tagObj.verification.verified
        ? 'verified'
        : 'unsigned'
      : 'not-applicable',
    commitSha,
    commitDate: commit.committer.date,
    commitAuthorDate: commit.author.date,
    commitMessage: commit.message.trim(),
    commitVerification:
      commit.verification && commit.verification.verified
        ? 'verified'
        : 'unsigned',
    rootTreeSha: treeSha,
    ...counts,
    expectedCommitShaFromPriorScout: EXPECTED_COMMIT,
    expectedCommitShaConfirmedFromWire: commitSha === EXPECTED_COMMIT,
  },
  requests: state.requests.map((r) => ({
    endpoint: r.endpoint,
    status: r.status,
    bytes: r.bytes,
    sha256: r.sha256,
    ...(r.stream ? { stream: r.stream } : {}),
  })),
  archive: {
    url: archiveUrl,
    bytes: a1.body.length,
    sha256: a1.digest,
    byteIdentical,
    secondStreamSha256: a2.digest,
  },
  transaction: {
    attemptedRequests: state.accepted,
    acceptedResponses: state.accepted,
    acceptedWireBytes: state.wireBytes,
    redirectsObserved: state.redirects,
    retries: 0,
    credentialsSent: 0,
  },
};

await writeFile(
  join(cacheRoot, 'raw', 'summary.json'),
  JSON.stringify(summary, null, 2),
);
console.log(JSON.stringify(summary, null, 2));

