const entries = tree.tree;
const counts = {
  treeEntries: entries.length,
  treeBlobs: entries.filter((e) => e.type === 'blob').length,
  treeDirectories: entries.filter((e) => e.type === 'tree').length,
  treeSymlinks: entries.filter((e) => e.mode === '120000').length,
  treeGitlinks: entries.filter((e) => e.type === 'commit').length,
  treeExecutableBlobs: entries.filter((e) => e.mode === '100755').length,
  treeTruncated: Boolean(tree.truncated),
