#!/usr/bin/env node
// Extract the acquired archive and reconcile it blob-for-blob against the
// recursive git tree, then scan for LFS pointers. Offline.
//
// Usage: node reconcile.mjs <cacheRoot> <evidenceRoot>

import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile, rm, readdir, stat, lstat } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { join, relative, sep } from 'node:path';

const cacheRoot = process.argv[2];
const evidenceRoot = process.argv[3];
const COMMIT = '2943c5c4f13c3ce4dece0abf4f9c39739dde4192';
const ROOT_NAME = `super-productivity-${COMMIT}`;

const extractDir = join(cacheRoot, 'verify', 'extracted');
await rm(extractDir, { recursive: true, force: true });
await mkdir(extractDir, { recursive: true });

// Inspect entry names before extracting: refuse traversal / absolute paths.
const listing = execFileSync(
  'tar',
  ['-tzf', join(cacheRoot, 'archive', 'archive-1.tar.gz')],
  { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 },
)
  .split('\n')
  .filter(Boolean);

const pathTraversalEntries = listing.filter((p) => p.split('/').includes('..')).length;
const absolutePathEntries = listing.filter((p) => p.startsWith('/')).length;
const roots = new Set(listing.map((p) => p.split('/')[0]));
if (pathTraversalEntries || absolutePathEntries) {
  throw new Error('unsafe archive entries');
}

execFileSync('tar', ['-xzf', join(cacheRoot, 'archive', 'archive-1.tar.gz'), '-C', extractDir]);

const srcRoot = join(extractDir, ROOT_NAME);

const gitBlob = (buf) =>
  createHash('sha1')
    .update(Buffer.concat([Buffer.from(`blob ${buf.length}\0`), buf]))
    .digest('hex');

async function walk(dir, acc = { files: [], dirs: [], special: [] }) {
  for (const name of await readdir(dir)) {
    const full = join(dir, name);
    const st = await lstat(full);
    if (st.isSymbolicLink()) acc.special.push(full);
    else if (st.isDirectory()) {
      acc.dirs.push(full);
      await walk(full, acc);
    } else if (st.isFile()) acc.files.push(full);
    else acc.special.push(full);
  }
  return acc;
}

const disk = await walk(srcRoot);
const tree = JSON.parse(await readFile(join(evidenceRoot, 'probe-tree.json'), 'utf8'));
const blobByPath = new Map(
  tree.tree.filter((e) => e.type === 'blob').map((e) => [e.path, e.sha]),
);

let mismatched = 0;
const missing = [];
const extra = [];
const lfsPointers = [];
const seen = new Set();

for (const file of disk.files) {
  const rel = relative(srcRoot, file).split(sep).join('/');
  seen.add(rel);
  const expected = blobByPath.get(rel);
  const buf = await readFile(file);
  if (!expected) {
    extra.push(rel);
    continue;
  }
  if (gitBlob(buf) !== expected) mismatched += 1;
  // LFS pointer scan: the spec's first line is the version URL.
  if (buf.length < 1024 && buf.slice(0, 45).toString('utf8').startsWith('version https://git-lfs.github.com/spec/')) {
    lfsPointers.push(rel);
  }
}
for (const p of blobByPath.keys()) if (!seen.has(p)) missing.push(p);

// normalized manifest: sorted "sha  path" lines over every regular file
const manifest = [...seen]
  .sort()
  .map((p) => `${blobByPath.get(p)}  ${p}`)
  .join('\n');
const normalizedManifestSha256 = createHash('sha256').update(manifest).digest('hex');

const digestOf = async (rel) => {
  try {
    const buf = await readFile(join(srcRoot, rel));
    return {
      path: rel,
      bytes: buf.length,
      gitBlobSha: gitBlob(buf),
      sha256: createHash('sha256').update(buf).digest('hex'),
    };
  } catch {
    return { path: rel, present: false };
  }
};

const keyFiles = {};
for (const rel of [
  'LICENSE',
  'package.json',
  'yarn.lock',
  'angular.json',
  'tsconfig.json',
  'tsconfig.worker.json',
  'src/tsconfig.app.json',
  '.nvmrc',
  '.travis.yml',
  'README.md',
]) {
  keyFiles[rel] = await digestOf(rel);
}

const gitattributes = listing.some((p) => p.endsWith('/.gitattributes'));

const out = {
  archiveRoot: [...roots][0],
  singleRoot: roots.size === 1,
  safeEntries: listing.length,
  regularFiles: disk.files.length,
  directories: disk.dirs.length,
  specialEntries: disk.special.length,
  gitBlobs: blobByPath.size,
  missingFiles: missing.length,
  extraFiles: extra.length,
  mismatchedBlobs: mismatched,
  missing,
  extra,
  pathTraversalEntries,
  absolutePathEntries,
  normalizedManifestSha256,
  lfs: {
    gitattributesPresent: gitattributes,
    pointerFiles: lfsPointers.length,
    pointerPaths: lfsPointers,
    scanned: disk.files.length,
  },
  keyFiles,
  verifiedSourceRoot: join(cacheRoot, 'verify', 'extracted', ROOT_NAME),
};

await writeFile(join(cacheRoot, 'raw', 'reconcile.json'), JSON.stringify(out, null, 2));
console.log(JSON.stringify({ ...out, missing: missing.slice(0, 10), extra: extra.slice(0, 10) }, null, 2));

