#!/usr/bin/env node
// Acquire the integrity facts for the one git-protocol dependency the acquired
// manifest declares: "jira2md": "git+https://github.com/johannesjo/J2M.git",
// lock-resolved to a bare commit. PM-RULED APPROVED under consent
// VL-LEGACY-CORPUS-2026-08-10.
//
// The resolved commit is read out of the acquired yarn.lock, not chosen here.
// Usage: node acquire-git-dependency.mjs <cacheRoot> <evidenceRoot> <sourceRoot>

import { createHash } from 'node:crypto';
import { mkdir, writeFile, appendFile, readFile } from 'node:fs/promises';
import { join } from 'node:path';

const cacheRoot = process.argv[2];
const evidenceRoot = process.argv[3];
const sourceRoot = process.argv[4];
const ledgerPath = join(evidenceRoot, 'probe-ledger.ndjson');

const lock = await readFile(join(sourceRoot, 'yarn.lock'), 'utf8');
const block = lock.match(
  /"jira2md@git\+https:\/\/github\.com\/johannesjo\/J2M\.git":\n([\s\S]*?)\n\n/,
);
if (!block) throw new Error('jira2md block not found in yarn.lock');
const resolved = block[1].match(/resolved "([^"]+)"/)[1];
const version = block[1].match(/version "([^"]+)"/)[1];
const commit = resolved.split('#')[1];
const hasIntegrity = /integrity /.test(block[1]);
if (!/^[0-9a-f]{40}$/.test(commit)) throw new Error(`not a bare sha: ${commit}`);

const OWNER = 'johannesjo';
const REPO = 'J2M';
const requests = [];

async function probe(url, { maxBytes = 16777216, stream } = {}) {
  const at = new Date().toISOString();
  const res = await fetch(url, {
    method: 'GET',
    redirect: 'manual',
    headers: {
      accept: url.startsWith('https://api.github.com')
        ? 'application/vnd.github+json'
        : 'application/octet-stream',
      'accept-encoding': 'identity',
      'user-agent': 'versionless-legacy-corpus-ingest',
    },
  });
  const location = res.headers.get('location');
  if (res.status >= 300 && res.status < 400) {
    const record = {
      at,
      completedAt: new Date().toISOString(),
      endpoint: url,
      method: 'GET',
      status: res.status,
      bytes: 0,
      sha256: null,
      location,
      redirectFollowed: false,
      purpose: 'git-protocol-dependency',
      credentialsSent: 0,
    };
    requests.push(record);
    await appendFile(ledgerPath, JSON.stringify(record) + '\n');
    return { redirected: true, location, record };
  }
  if (res.status !== 200) throw new Error(`status ${res.status} for ${url}`);
  const body = Buffer.from(await res.arrayBuffer());
  if (body.length > maxBytes) throw new Error(`cap exceeded for ${url}`);
  const digest = createHash('sha256').update(body).digest('hex');
  const record = {
    at,
    completedAt: new Date().toISOString(),
    endpoint: url,
    method: 'GET',
    status: res.status,
    bytes: body.length,
    sha256: digest,
    purpose: 'git-protocol-dependency',
    credentialsSent: 0,
    ...(stream ? { stream } : {}),
  };
  requests.push(record);
  await appendFile(ledgerPath, JSON.stringify(record) + '\n');
  return { body, digest, record };
}

const commitRes = await probe(
  `https://api.github.com/repos/${OWNER}/${REPO}/git/commits/${commit}`,
);
const commitObj = JSON.parse(commitRes.body.toString('utf8'));

const treeRes = await probe(
  `https://api.github.com/repos/${OWNER}/${REPO}/git/trees/${commitObj.tree.sha}?recursive=1`,
);
const tree = JSON.parse(treeRes.body.toString('utf8'));

const archiveUrl = `https://codeload.github.com/${OWNER}/${REPO}/tar.gz/${commit}`;
const t1 = await probe(archiveUrl, { maxBytes: 33554432, stream: 1 });
const t2 = await probe(archiveUrl, { maxBytes: 33554432, stream: 2 });

await mkdir(join(cacheRoot, 'git-dependency'), { recursive: true });
await writeFile(join(cacheRoot, 'git-dependency', 'jira2md-1.tar.gz'), t1.body);
await writeFile(join(cacheRoot, 'git-dependency', 'jira2md-2.tar.gz'), t2.body);

const licenceEntry = tree.tree.find((e) =>
  /^(LICENSE|LICENCE|LICENSE\.md|COPYING)$/i.test(e.path),
