const out = {
  declaredIn: 'package.json devDependencies',
  declaredSpecifier: 'git+https://github.com/johannesjo/J2M.git',
  lockResolvedTo: resolved,
  lockedVersion: version,
  resolvedCommitSha: commit,
  commitDate: commitObj.committer.date,
  commitMessage: commitObj.message.trim(),
  commitVerification:
    commitObj.verification && commitObj.verification.verified
      ? 'verified'
      : 'unsigned',
  rootTreeSha: commitObj.tree.sha,
  treeEntries: tree.tree.length,
  treeBlobs: tree.tree.filter((e) => e.type === 'blob').length,
  licenceFileInTree: licenceEntry ? licenceEntry.path : null,
  licenceBlobSha: licenceEntry ? licenceEntry.sha : null,
  tarball: {
    url: archiveUrl,
    bytes: t1.body.length,
    sha256: t1.digest,
    secondStreamSha256: t2.digest,
    byteIdentical: t1.digest === t2.digest && t1.body.equals(t2.body),
  },
  lockIntegrityHashPresent: hasIntegrity,
  requests: requests.map((r) => ({
    endpoint: r.endpoint,
    status: r.status,
    bytes: r.bytes,
    sha256: r.sha256,
    ...(r.stream ? { stream: r.stream } : {}),
    ...(r.location ? { location: r.location } : {}),
  })),
